/**
 * freshpet-invoice-pdf — reusable server-side PDF renderer for Freshpet
 * billing runs (PM + Quarterly Reactive). Self-contained ESM module: pdf-lib
 * only, no cross-repo imports, no network fetches — the two brand logos are
 * base64-embedded below.
 *
 * PAGE 1 mirrors brix-order's paper-billing invoice template
 * (brix-order netlify/functions/_lib/invoice-pdf.ts): US-Letter, navy accent
 * strip, Alameda Point Beverage Group masthead lockup (Brix lead mark + navy
 * rule + Alameda Soda navy wordmark), right-aligned INVOICE title block,
 * FROM / BILL TO bordered boxes, a navy meta strip, a navy-header line-item
 * table with WHITE column labels (one summary row), a bordered totals box, and
 * a navy remittance footer with the "Powered by Brix Beverage" co-brand mark.
 *
 * PAGE 2+ is an "Assets billed" report: a paginated table
 * (Store | City | Serial | Model | Warranty) listing every asset, with a
 * compact running header repeated on each continuation page.
 *
 * Everything is grayscale-legible (these invoices may be mailed B&W) — color
 * is decorative, never load-bearing; the navy table header keeps WHITE labels.
 *
 * Single export:
 *   export async function renderFreshpetInvoicePdf(input) -> Uint8Array
 *
 * input = {
 *   invoiceRef,     // string  — shown as the Invoice #
 *   billingType,    // 'pm' | 'reactive' — page-1 subtitle only
 *   customerName,   // string
 *   billTo,         // multiline string | null — address block
 *   invoiceDate,    // ISO/date string
 *   dueDate,        // ISO/date string | null
 *   summaryLabel,   // string — the single page-1 line-item description
 *   qty,            // integer — count of assets/visits
 *   rate,           // number  — unit price
 *   total,          // number  — qty * rate
 *   assets,         // Array<{ store, city, serial, model, warranty }>
 * }
 */

import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';

// ── Embedded brand artwork (verbatim from brix-order brand-assets.ts) ────────
// Brix Beverage full logo PNG (1280x578, ~2.21:1) — masthead lead mark +
// running-header / footer co-brand.
const BRIX_LOGO_FULL_PNG_ASPECT = 1280 / 578;
const BRIX_LOGO_FULL_PNG_BASE64 =
  '';

// Alameda Soda Co. NAVY wordmark PNG (1920x321, ~5.98:1) — masthead secondary
// mark + continuation running header.
const ALAMEDA_SODA_LOGO_NAVY_PNG_ASPECT = 1920 / 321;
const ALAMEDA_SODA_LOGO_NAVY_PNG_BASE64 =
  '';

// ── Company constants (from brix-order brand-info.ts, inlined) ───────────────
const COMPANY_LEGAL = 'Alameda Point Beverage Group Inc.';
const POWERED_BY = 'Powered by Brix Beverage';
const FROM_LINES = ['Brix Beverage', '1951 Monarch Street #200', 'Alameda, CA 94501'];

// ── Page geometry (US Letter, points) ───────────────────────────────────────
const PAGE_W = 612;
const PAGE_H = 792;
const MARGIN = 54; // ~0.75"
const CONTENT_W = PAGE_W - MARGIN * 2;
const CONTENT_R = MARGIN + CONTENT_W;

// ── Typographic scale ───────────────────────────────────────────────────────
const TITLE = 22;
const SUBTITLE = 10;
const HEAD = 11;
const LABEL = 8.5;
const BODY = 10;
const NUM = 9.5;
const LEGAL = 8;

// ── Spacing rhythm ──────────────────────────────────────────────────────────
const LINE_H = 13;
const ROW_H = 16;
const GAP_SM = 8;
const GAP_MD = 16;
const GAP_LG = 24;
const PAD = 8;

// ── Brand ink ─────────────────────────────────────────────────────────────
const NAVY = rgb(0x1f / 255, 0x4e / 255, 0x79 / 255); // #1F4E79
const NAVY_DEEP = rgb(0x14 / 255, 0x33 / 255, 0x58 / 255); // #143358
const BLACK = rgb(0.1, 0.1, 0.1);
const GRAY = rgb(0.4, 0.4, 0.4);
const WHITE = rgb(1, 1, 1);
const RULE = rgb(0.78, 0.78, 0.8);
const FILL = rgb(0.965, 0.965, 0.975);

// ── Rule weights / bars ─────────────────────────────────────────────────────
const RULE_DIVIDER = 1;
const RULE_BOX = 0.75;
const RULE_ROW = 0.5;
const ACCENT_STRIP_H = 6;
const TABLE_HEAD_H = 18;

// ── Masthead lockup dims ────────────────────────────────────────────────────
const BRIX_LEAD_H = 50;
const LOCKUP_GAP = 16;
const LOCKUP_ALAMEDA_RATIO = 0.58;
const LOCKUP_RULE_W = 1.5;
const RUNNING_LOGO_H = 16;
const COBRAND_LOGO_H = 14;

// ── Footer band ──────────────────────────────────────────────────────────────
const FOOTER_BAND_H = 62;
const SMALL = 8;
const TINY = 7.5;
const SMALL_LINE_H = 10.5;
const FOOTER_THANKS = 'Thank you for your business.';
const FOOTER_REMIT =
  COMPANY_LEGAL + ' - 1951 Monarch Street #200 - Alameda, CA 94501 - Make checks payable to Brix Beverage';
const FOOTER_CONTACT = '510-564-2700 - service@brixbev.com - brixbev.com';

// ── Formatting helpers ──────────────────────────────────────────────────────
function fmtUsd(n) {
  const v = Number.isFinite(n) ? n : 0;
  const abs = Math.abs(v).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  return v < 0 ? '($' + abs + ')' : '$' + abs;
}

function fmtQty(q) {
  if (q == null || !Number.isFinite(q)) return '';
  return Number.isInteger(q) ? String(q) : q.toLocaleString('en-US', { maximumFractionDigits: 2 });
}

function fmtDate(s) {
  if (!s) return '—';
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s));
  if (!m) return String(s);
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  return d.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

// ── Draw primitives ─────────────────────────────────────────────────────────
function drawText(page, text, x, y, font, size, color = BLACK) {
  page.drawText(text, { x, y, size, font, color });
}

function drawRight(page, text, rightX, y, font, size, color = BLACK) {
  const w = font.widthOfTextAtSize(text, size);
  page.drawText(text, { x: rightX - w, y, size, font, color });
}

function drawCentered(page, text, y, font, size, color = BLACK) {
  const w = font.widthOfTextAtSize(text, size);
  page.drawText(text, { x: MARGIN + (CONTENT_W - w) / 2, y, size, font, color });
}

function fit(text, font, size, maxW) {
  const t0 = text == null ? '' : String(text);
  if (font.widthOfTextAtSize(t0, size) <= maxW) return t0;
  let t = t0;
  while (t.length > 1 && font.widthOfTextAtSize(t + '…', size) > maxW) {
    t = t.slice(0, -1);
  }
  return t + '…';
}

function drawBox(page, x, y, w, h, opts = {}) {
  page.drawRectangle({
    x,
    y,
    width: w,
    height: h,
    color: opts.fill,
    borderColor: opts.border,
    borderWidth: opts.border ? (opts.borderW ?? RULE_BOX) : undefined,
  });
}

function newPage(ctx) {
  return ctx.doc.addPage([PAGE_W, PAGE_H]);
}

function drawAccentStrip(page) {
  page.drawRectangle({
    x: 0,
    y: PAGE_H - ACCENT_STRIP_H,
    width: PAGE_W,
    height: ACCENT_STRIP_H,
    color: NAVY,
  });
}

// The Alameda Point Beverage Group brand lockup: large Brix mark (left),
// vertical navy rule, Alameda Soda navy wordmark (secondary, centered on rule).
function drawBrandLockup(ctx, page, x, top) {
  const brixW = BRIX_LEAD_H * BRIX_LOGO_FULL_PNG_ASPECT;
  page.drawImage(ctx.brix, { x, y: top - BRIX_LEAD_H, width: brixW, height: BRIX_LEAD_H });

  const lineX = x + brixW + LOCKUP_GAP;
  page.drawLine({
    start: { x: lineX, y: top },
    end: { x: lineX, y: top - BRIX_LEAD_H },
    thickness: LOCKUP_RULE_W,
    color: NAVY,
  });

  const alaH = Math.round(BRIX_LEAD_H * LOCKUP_ALAMEDA_RATIO);
  const alaW = alaH * ALAMEDA_SODA_LOGO_NAVY_PNG_ASPECT;
  const alaX = lineX + LOCKUP_GAP;
  const alaY = top - BRIX_LEAD_H / 2 - alaH / 2;
  page.drawImage(ctx.alamedaNavy, { x: alaX, y: alaY, width: alaW, height: alaH });

  return { bottom: top - BRIX_LEAD_H, width: alaX + alaW - x };
}

function drawMasthead(ctx, page, input) {
  drawAccentStrip(page);
  const top = PAGE_H - ACCENT_STRIP_H - GAP_LG;

  const lock = drawBrandLockup(ctx, page, MARGIN, top);

  const legalY = lock.bottom - LEGAL - 3;
  drawText(page, COMPANY_LEGAL, MARGIN, legalY, ctx.font, LEGAL, GRAY);

  // Title block (right).
  const subtitle = input.billingType === 'reactive' ? 'Quarterly Reactive Service' : 'Preventive Maintenance';
  drawRight(page, 'INVOICE', CONTENT_R, top - TITLE + 4, ctx.bold, TITLE, NAVY_DEEP);
  drawRight(page, subtitle, CONTENT_R, top - TITLE - SUBTITLE + 1, ctx.font, SUBTITLE, GRAY);
  drawRight(
    page,
    '#' + input.invoiceRef,
    CONTENT_R,
    top - TITLE - SUBTITLE - HEAD + 1,
    ctx.bold,
    HEAD,
    BLACK,
  );
  drawRight(
    page,
    fmtDate(input.invoiceDate),
    CONTENT_R,
    top - TITLE - SUBTITLE - HEAD - LINE_H + 2,
    ctx.font,
    NUM,
    GRAY,
  );

  const titleDepth = TITLE + SUBTITLE + HEAD + LINE_H;
  const leadDepth = top - legalY;
  const mastheadDepth = Math.max(leadDepth, titleDepth);
  const ry = top - mastheadDepth - GAP_SM;
  page.drawLine({
    start: { x: MARGIN, y: ry },
    end: { x: CONTENT_R, y: ry },
    thickness: RULE_DIVIDER,
    color: NAVY,
  });
  return ry - GAP_LG;
}

// Compact branded running header for continuation pages.
function drawRunningHeader(ctx, page, label) {
  drawAccentStrip(page);
  const top = PAGE_H - ACCENT_STRIP_H - GAP_MD;
  const logoH = RUNNING_LOGO_H;
  const logoW = logoH * ALAMEDA_SODA_LOGO_NAVY_PNG_ASPECT;
  page.drawImage(ctx.alamedaNavy, { x: MARGIN, y: top - logoH, width: logoW, height: logoH });
  drawRight(page, label, CONTENT_R, top - 13, ctx.font, NUM, GRAY);
  const ry = top - logoH - GAP_SM;
  page.drawLine({
    start: { x: MARGIN, y: ry },
    end: { x: CONTENT_R, y: ry },
    thickness: RULE_BOX,
    color: NAVY,
  });
  return ry - GAP_MD;
}

// Side-by-side FROM | BILL TO bordered boxes.
function drawAddressBoxes(page, ctx, y, fromLines, toLines) {
  const gutter = 16;
  const boxW = (CONTENT_W - gutter) / 2;
  const addrRows = Math.max(fromLines.length, toLines.length);
  const boxH = PAD + LINE_H + addrRows * LINE_H + PAD;
  const top = y;
  const leftX = MARGIN;
  const rightX = MARGIN + boxW + gutter;

  for (const bx of [leftX, rightX]) {
    drawBox(page, bx, top - boxH, boxW, boxH, { fill: FILL, border: RULE });
  }

  const labelY = top - PAD - LABEL;
  drawText(page, 'FROM', leftX + PAD, labelY, ctx.bold, LABEL, NAVY);
  drawText(page, 'BILL TO', rightX + PAD, labelY, ctx.bold, LABEL, NAVY);

  const firstRowY = labelY - LINE_H - 2;
  const colW = boxW - PAD * 2;
  for (let i = 0; i < addrRows; i++) {
    const rowY = firstRowY - i * LINE_H;
    const emphasize = i === 0;
    const f = emphasize ? ctx.bold : ctx.font;
    if (fromLines[i]) {
      drawText(page, fit(fromLines[i], f, BODY, colW), leftX + PAD, rowY, f, BODY, BLACK);
    }
    if (toLines[i]) {
      drawText(page, fit(toLines[i], f, BODY, colW), rightX + PAD, rowY, f, BODY, BLACK);
    }
  }
  return top - boxH - GAP_MD;
}

// Meta strip: a row of bordered/lightly-filled cells.
function drawMetaStrip(page, ctx, y, cells) {
  const cellW = CONTENT_W / cells.length;
  const cellH = PAD + LABEL + 6 + NUM + PAD;
  const top = y;
  cells.forEach((c, i) => {
    const cx = MARGIN + cellW * i;
    drawBox(page, cx, top - cellH, cellW, cellH, { fill: FILL, border: RULE });
    drawText(page, c.label, cx + PAD, top - PAD - LABEL, ctx.bold, LABEL, NAVY);
    drawText(
      page,
      c.value,
      cx + PAD,
      top - PAD - LABEL - 6 - NUM + 1,
      c.emphasize ? ctx.bold : ctx.font,
      NUM,
      BLACK,
    );
  });
  return top - cellH - GAP_LG;
}

// Page-1 line-item table head (Item / Qty / Unit / Amount).
const COL_ITEM = MARGIN + PAD;
const COL_QTY_R = MARGIN + 330;
const COL_UNIT_R = MARGIN + 415;
const COL_AMT_R = CONTENT_R - PAD;
const ITEM_MAX_W = 290;

function drawTableHead(page, ctx, y) {
  page.drawRectangle({
    x: MARGIN,
    y: y - TABLE_HEAD_H,
    width: CONTENT_W,
    height: TABLE_HEAD_H,
    color: NAVY,
  });
  const ty = y - TABLE_HEAD_H + 6;
  drawText(page, 'ITEM', COL_ITEM, ty, ctx.bold, LABEL, WHITE);
  drawRight(page, 'QTY', COL_QTY_R, ty, ctx.bold, LABEL, WHITE);
  drawRight(page, 'UNIT', COL_UNIT_R, ty, ctx.bold, LABEL, WHITE);
  drawRight(page, 'AMOUNT', COL_AMT_R, ty, ctx.bold, LABEL, WHITE);
  return y - TABLE_HEAD_H;
}

// Assets table (page 2+) column geometry.
const A_STORE_X = MARGIN + PAD;
const A_CITY_X = MARGIN + 165;
const A_SERIAL_X = MARGIN + 275;
const A_MODEL_X = MARGIN + 375;
const A_WARR_X = MARGIN + 445;
const A_STORE_MAX_W = 150;
const A_CITY_MAX_W = 100;
const A_SERIAL_MAX_W = 90;
const A_MODEL_MAX_W = 62;
const A_WARR_MAX_W = CONTENT_R - A_WARR_X - PAD;

function drawAssetsTableHead(page, ctx, y) {
  page.drawRectangle({
    x: MARGIN,
    y: y - TABLE_HEAD_H,
    width: CONTENT_W,
    height: TABLE_HEAD_H,
    color: NAVY,
  });
  const ty = y - TABLE_HEAD_H + 6;
  drawText(page, 'STORE', A_STORE_X, ty, ctx.bold, LABEL, WHITE);
  drawText(page, 'CITY', A_CITY_X, ty, ctx.bold, LABEL, WHITE);
  drawText(page, 'SERIAL', A_SERIAL_X, ty, ctx.bold, LABEL, WHITE);
  drawText(page, 'MODEL', A_MODEL_X, ty, ctx.bold, LABEL, WHITE);
  drawText(page, 'WARRANTY', A_WARR_X, ty, ctx.bold, LABEL, WHITE);
  return y - TABLE_HEAD_H;
}

function drawRowRule(page, y) {
  page.drawLine({
    start: { x: MARGIN, y },
    end: { x: CONTENT_R, y },
    thickness: RULE_ROW,
    color: RULE,
  });
}

// Multi-line contact footer band.
function drawFooterBand(page, ctx) {
  const ruleY = MARGIN - 6 + FOOTER_BAND_H;
  page.drawLine({
    start: { x: MARGIN, y: ruleY },
    end: { x: CONTENT_R, y: ruleY },
    thickness: 0.75,
    color: NAVY,
  });

  const logoW = COBRAND_LOGO_H * BRIX_LOGO_FULL_PNG_ASPECT;
  const logoY = ruleY - 5 - COBRAND_LOGO_H;
  const labelW = ctx.font.widthOfTextAtSize(POWERED_BY, TINY);
  drawText(page, POWERED_BY, MARGIN, logoY + (COBRAND_LOGO_H - TINY) / 2 + 0.5, ctx.font, TINY, GRAY);
  page.drawImage(ctx.brix, {
    x: MARGIN + labelW + 8,
    y: logoY,
    width: logoW,
    height: COBRAND_LOGO_H,
  });

  const thanksY = logoY - SMALL_LINE_H;
  drawCentered(page, FOOTER_THANKS, thanksY, ctx.bold, SMALL, NAVY);

  let ly = thanksY - SMALL_LINE_H - 2;
  for (const ln of [
    { text: FOOTER_REMIT, font: ctx.bold, color: BLACK },
    { text: FOOTER_CONTACT, font: ctx.font, color: BLACK },
  ]) {
    drawCentered(page, fit(ln.text, ln.font, SMALL, CONTENT_W), ly, ln.font, SMALL, ln.color);
    ly -= SMALL_LINE_H;
  }
}

function stampPageNumbers(doc, font) {
  const pages = doc.getPages();
  const total = pages.length;
  if (total < 2) return;
  pages.forEach((p, i) => {
    const label = 'Page ' + (i + 1) + ' of ' + total;
    const w = font.widthOfTextAtSize(label, TINY);
    p.drawText(label, { x: CONTENT_R - w, y: PAGE_H - 16, size: TINY, font, color: GRAY });
  });
}

function billToLines(customerName, billTo) {
  const lines = [customerName == null ? '' : String(customerName)];
  if (billTo) {
    for (const ln of String(billTo).split(/\r?\n/)) {
      const t = ln.trim();
      if (t) lines.push(t);
    }
  }
  return lines.map((s) => (s == null ? '' : String(s).trim())).filter(Boolean);
}

/**
 * Render the Freshpet invoice + per-asset report.
 * @param {object} input see module header for the shape.
 * @returns {Promise<Uint8Array>} PDF bytes.
 */
export async function renderFreshpetInvoicePdf(input) {
  const invoiceRef = input && input.invoiceRef != null ? String(input.invoiceRef) : '';
  const assets = Array.isArray(input && input.assets) ? input.assets : [];
  const total = Number.isFinite(input && input.total) ? input.total : 0;

  const doc = await PDFDocument.create();
  doc.setTitle('Brix Beverage — Invoice ' + invoiceRef);
  doc.setProducer('apbg-billing / freshpet-invoice-pdf');
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const brix = await doc.embedPng(Buffer.from(BRIX_LOGO_FULL_PNG_BASE64, 'base64'));
  const alamedaNavy = await doc.embedPng(Buffer.from(ALAMEDA_SODA_LOGO_NAVY_PNG_BASE64, 'base64'));
  const ctx = { doc, font, bold, brix, alamedaNavy };

  // ── PAGE 1 — branded invoice ───────────────────────────────────────────────
  let page = newPage(ctx);
  let y = drawMasthead(ctx, page, input || {});

  y = drawAddressBoxes(page, ctx, y, FROM_LINES, billToLines(input && input.customerName, input && input.billTo));

  y = drawMetaStrip(page, ctx, y, [
    { label: 'INVOICE DATE', value: fmtDate(input && input.invoiceDate) },
    { label: 'DUE DATE', value: fmtDate(input && input.dueDate) },
    { label: 'BALANCE DUE', value: fmtUsd(total), emphasize: true },
  ]);

  // Single summary line-item row.
  y = drawTableHead(page, ctx, y);
  {
    const bandTop = y;
    const nameY = bandTop - ROW_H + 5;
    const label = input && input.summaryLabel ? String(input.summaryLabel) : 'Freshpet service';
    drawText(page, fit(label, font, NUM, ITEM_MAX_W), COL_ITEM, nameY, font, NUM, BLACK);
    drawRight(page, fmtQty(input && input.qty != null ? input.qty : null), COL_QTY_R, nameY, font, NUM, BLACK);
    drawRight(
      page,
      input && input.rate != null ? fmtUsd(input.rate) : '',
      COL_UNIT_R,
      nameY,
      font,
      NUM,
      BLACK,
    );
    drawRight(page, fmtUsd(total), COL_AMT_R, nameY, font, NUM, BLACK);
    y = bandTop - ROW_H;
    drawRowRule(page, y);
  }

  // Totals box (Subtotal / Total / Balance Due).
  const totalsW = 220;
  const totalsH = PAD + LINE_H + LINE_H + LINE_H + PAD;
  y -= GAP_MD;
  const totalsX = CONTENT_R - totalsW;
  const totalsTop = y;
  drawBox(page, totalsX, totalsTop - totalsH, totalsW, totalsH, {
    fill: FILL,
    border: NAVY,
    borderW: RULE_BOX,
  });
  const labelX = totalsX + PAD;
  const valR = CONTENT_R - PAD;
  let ty = totalsTop - PAD - NUM;
  drawText(page, 'Subtotal', labelX, ty, font, NUM, GRAY);
  drawRight(page, fmtUsd(total), valR, ty, font, NUM, BLACK);
  ty -= LINE_H;
  drawText(page, 'Total', labelX, ty, font, NUM, GRAY);
  drawRight(page, fmtUsd(total), valR, ty, font, NUM, BLACK);
  ty -= LINE_H;
  drawText(page, 'BALANCE DUE', labelX, ty, bold, NUM, NAVY_DEEP);
  drawRight(page, fmtUsd(total), valR, ty, bold, NUM, NAVY_DEEP);

  // Footer band on page 1.
  drawFooterBand(page, ctx);

  // ── PAGE 2+ — Assets billed report ─────────────────────────────────────────
  let assetPageNo = 1;
  const newAssetPage = () => {
    const p = newPage(ctx);
    const cy = drawRunningHeader(ctx, p, invoiceRef + ' — Assets (page ' + assetPageNo + ')');
    assetPageNo += 1;
    return { p, cy };
  };

  {
    let { p, cy } = newAssetPage();
    drawText(p, 'ASSETS BILLED', MARGIN, cy - LABEL, bold, LABEL, NAVY);
    cy = cy - LABEL - GAP_SM;

    if (assets.length === 0) {
      drawText(p, 'No asset detail.', MARGIN, cy - BODY, font, BODY, GRAY);
    } else {
      cy = drawAssetsTableHead(p, ctx, cy);
      const BOTTOM_LIMIT = MARGIN + 24;
      for (const a of assets) {
        if (cy - ROW_H < BOTTOM_LIMIT) {
          const np = newAssetPage();
          p = np.p;
          cy = np.cy;
          cy = drawAssetsTableHead(p, ctx, cy);
        }
        const bandTop = cy;
        const rowY = bandTop - ROW_H + 5;
        const store = a && a.store != null ? String(a.store) : '';
        const city = a && a.city != null ? String(a.city) : '';
        const serial = a && a.serial != null ? String(a.serial) : '';
        const model = a && a.model != null ? String(a.model) : '';
        const warranty = a && a.warranty != null ? String(a.warranty) : '';
        drawText(p, fit(store, font, NUM, A_STORE_MAX_W), A_STORE_X, rowY, font, NUM, BLACK);
        drawText(p, fit(city, font, NUM, A_CITY_MAX_W), A_CITY_X, rowY, font, NUM, BLACK);
        drawText(p, fit(serial, font, NUM, A_SERIAL_MAX_W), A_SERIAL_X, rowY, font, NUM, BLACK);
        drawText(p, fit(model, font, NUM, A_MODEL_MAX_W), A_MODEL_X, rowY, font, NUM, BLACK);
        drawText(p, fit(warranty, font, NUM, A_WARR_MAX_W), A_WARR_X, rowY, font, NUM, GRAY);
        cy = bandTop - ROW_H;
        drawRowRule(p, cy);
      }
    }
  }

  stampPageNumbers(doc, font);
  return doc.save();
}
